ReplacementContent:
"                // Calculate payment breakdown totals
                const pmTotals = recentOrders.reduce((acc, o) => {
                  if (o.status === 'CANCELLED' || o.status === 'DELETED') return acc;
                  if (o.status === 'FREE' || String(o.payment_method || '').toUpperCase() === 'FREE' || String(o.payment_method || '').toUpperCase() === 'COMPLIMENTARY') return acc;

                  const method = String(o.payment_method || 'CASH').toUpperCase();
                  const amt = parseFloat(o.total_price || 0);

                  if (method.includes('CARD')) acc.Card += amt;
                  else if (method.includes('CASH')) acc.Cash += amt;
                  else if (method.includes('GOOGLEPAY') || method.includes('GPAY')) acc.GooglePay += amt;
                  else if (method.includes('PAYTM')) acc.Paytm += amt;
                  else if (method.includes('UPI')) acc.UPI += amt;
                  return acc;
                }, { Card: 0, Cash: 0, GooglePay: 0, Paytm: 0, UPI: 0 });"

